import React, { useState } from "react";
import { Container, Row, Col, Card, Button } from "react-bootstrap";
import { toast } from "react-toastify";

const DashboardMultiRole = ({ user }) => {
  const [role, setRole] = useState(user?.role || "user");

  const handleAction = (msg) => {
    toast.info(msg);
  };

  return (
    <div>
      {/* ✅ Navbar */}
      <div
        className="bg-primary text-white p-3"
        style={{
          position: "sticky",
          top: 0,
          zIndex: 1000,
        }}
      >
        <h4 className="m-0">BRIRoom Dashboard</h4>
      </div>

      <Container fluid>
        <Row>
          {/* ✅ Sidebar Kiri */}
          <Col
            md={2}
            className="bg-light p-3 border-end"
            style={{
              height: "100vh",
              position: "sticky",
              top: "56px", // tinggi navbar
              overflowY: "auto",
            }}
          >
            <h6>Menu</h6>
            {role === "user" && (
              <>
                <Button
                  variant="primary"
                  className="w-100 mb-2"
                  onClick={() => handleAction("Ajukan Permintaan")}
                >
                  Ajukan Permintaan
                </Button>
              </>
            )}
            {role === "admin" && (
              <>
                <Button
                  variant="success"
                  className="w-100 mb-2"
                  onClick={() => handleAction("Lihat Laporan")}
                >
                  Lihat Laporan
                </Button>
              </>
            )}
            {role === "logistik" && (
              <>
                <Button
                  variant="warning"
                  className="w-100 mb-2"
                  onClick={() => handleAction("Kelola Jadwal")}
                >
                  Kelola Jadwal
                </Button>
              </>
            )}
          </Col>

          {/* ✅ Konten Tengah */}
          <Col
            md={8}
            className="p-3"
            style={{
              minHeight: "100vh",
              overflowY: "auto",
            }}
          >
            <Card className="mb-3">
              <Card.Body>
                <h5>Selamat Datang, {role.toUpperCase()}</h5>
                <p>
                  Ini adalah dashboard untuk role <b>{role}</b>. Sesuaikan menu
                  di kiri & kanan sesuai hak akses.
                </p>
              </Card.Body>
            </Card>
            {[...Array(20)].map((_, i) => (
              <Card className="mb-3" key={i}>
                <Card.Body>Konten {i + 1}</Card.Body>
              </Card>
            ))}
          </Col>

          {/* ✅ Sidebar Kanan */}
          <Col
            md={2}
            className="bg-light p-3 border-start"
            style={{
              height: "100vh",
              position: "sticky",
              top: "56px", // tinggi navbar
              overflowY: "auto",
            }}
          >
            <h6>Info</h6>
            <Card className="mb-2">
              <Card.Body>Notifikasi</Card.Body>
            </Card>
            <Card className="mb-2">
              <Card.Body>Status Permintaan</Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </div>
  );
};

export default DashboardMultiRole;
